def command_validate_scene_plan(args: argparse.Namespace) -> int:
    repo_root = Path(args.repo_root).resolve()
    profile = load_json(Path(args.profile))
    plan = load_json(Path(args.plan))
    challenge = load_json(Path(args.challenge))
    deliberation = load_json(Path(args.deliberation))
    gate = load_json(Path(args.design_gate))
    packet = load_json(Path(args.precedent_packet))
    errors: list[str] = []
    if not validate_profile_hash(profile):
        errors.append("compiled profile hash is invalid")
    errors.extend(validate_scene_plan_data(profile, plan))
    errors.extend(validate_screen_text_registration_binding(profile, plan, repo_root))
    if int(profile.get("autopilot_contract_version") or 0) >= 2:
        spine = load_json(Path(args.episode_spine))
        batch_plan = load_json(Path(args.batch_plan))
        errors.extend(validate_scene_planning_chain(plan, spine, batch_plan))
    errors.extend(validate_design_chain_data(profile, plan, challenge, deliberation, gate, packet))
    artifact_paths = {
        "profile": Path(args.profile),
        "plan": Path(args.plan),
        "challenge": Path(args.challenge),
        "deliberation": Path(args.deliberation),
        "design_gate": Path(args.design_gate),
        "precedent_packet": Path(args.precedent_packet),
        "episode_spine": Path(args.episode_spine),
        "batch_plan": Path(args.batch_plan),
    }
    result = {
        "schema": "lecture-animation-scene-plan-validation-v1",
        "valid": not errors,
        "errors": errors,
        "scene_slug": plan.get("scene_slug"),
        "profile_hash": profile.get("profile_hash"),
        "plan_hash": plan.get("plan_hash") or object_hash(plan),
        "artifacts": {
            key: artifact_snapshot(path, repo_root)
            for key, path in artifact_paths.items()
        },
    }
    result["validation_hash"] = object_hash(result)
    output = str(getattr(args, "output", "") or "").strip()
    if output:
        write_json(Path(output), result)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    return 0 if not errors else 2


def validate_scene_plan_validation_receipt(
    validation: dict[str, Any],
    repo_root: Path,
) -> list[str]:
    errors: list[str] = []
    if validation.get("schema") != "lecture-animation-scene-plan-validation-v1":
        errors.append("scene-plan validation receipt schema is invalid")
    if not validate_hashed_record(validation, "validation_hash"):
        errors.append("scene-plan validation receipt hash is invalid")
    if validation.get("valid") is not True or validation.get("errors") not in ([], None):
        errors.append("scene-plan validation receipt did not pass")
    artifacts = validation.get("artifacts")
    required = {
        "profile",
        "plan",
        "challenge",
        "deliberation",
        "design_gate",
        "precedent_packet",
        "episode_spine",
        "batch_plan",
    }
    if not isinstance(artifacts, dict) or set(artifacts) != required:
        errors.append("scene-plan validation receipt artifact set is incomplete")
        return errors
    for key, bound in artifacts.items():
        if not isinstance(bound, dict):
            errors.append(f"scene-plan validation artifact {key} is malformed")
            continue
        raw_path = str(bound.get("path", "")).strip()
        if not raw_path:
            errors.append(f"scene-plan validation artifact {key} has no path")
            continue
        path = resolve_stored_path(raw_path, repo_root)
        try:
            current = artifact_snapshot(path, repo_root)
        except PipelineError as exc:
            errors.append(str(exc))
            continue
        for field in ("path", "kind", "sha256", "size", "file_count"):
            if current.get(field) != bound.get(field):
                errors.append(
                    f"scene-plan validation artifact {key} is stale: {field}"
                )
                break
    return errors


def parse_visual_plan_probe_evidence(
    raw_values: list[str],
    repo_root: Path,
) -> list[dict[str, Any]]:
    probes: list[dict[str, Any]] = []
    seen: set[tuple[str, str]] = set()
    for raw in raw_values:
        if "=" not in raw:
            raise PipelineError(
                "visual plan probe must use keynote|keyframe|wireframe=path"
            )
        kind, path_raw = (part.strip() for part in raw.split("=", 1))
        if kind not in SUPPORTED_PROBE_KINDS or not path_raw:
            raise PipelineError(
                "visual plan probe must use keynote|keyframe|wireframe=path"
            )
        path = resolve_stored_path(path_raw, repo_root)
        snapshot = artifact_snapshot(path, repo_root)
        identity = (kind, str(snapshot["path"]))
        if identity in seen:
            raise PipelineError("duplicate visual plan probe evidence")
        seen.add(identity)
        probes.append({"kind": kind, "artifact": snapshot})
    return probes


def command_prepare_visual_plan_review(args: argparse.Namespace) -> int:
    repo_root = Path(args.repo_root).resolve()
    plan = load_json(Path(args.plan))
    validation_path = resolve_stored_path(args.scene_plan_validation, repo_root)
    validation = load_json(validation_path)
    validation_errors = validate_scene_plan_validation_receipt(
        validation,
        repo_root,
    )
    if validation_errors:
        raise PipelineError(
            "visual plan review requires a current scene-plan validation: "
            + " | ".join(validation_errors)
        )
    plan_binding = validation.get("artifacts", {}).get("plan", {})
    current_plan = artifact_snapshot(Path(args.plan), repo_root)
    for field in ("path", "kind", "sha256", "size", "file_count"):
        if current_plan.get(field) != plan_binding.get(field):
            raise PipelineError(
                "visual plan review plan differs from the validated detailed plan"
            )
    author_agent_id = str(args.author_agent_id).strip()
    reviewer_agent_id = str(args.reviewer_agent_id).strip()
    if not author_agent_id or not reviewer_agent_id:
        raise PipelineError("visual plan review requires author and reviewer identities")
    if author_agent_id == reviewer_agent_id:
        raise PipelineError("visual plan review reviewer must be independent")
    validation_binding = artifact_snapshot(validation_path, repo_root)
    scene_production_path = resolve_stored_path(args.scene_production, repo_root)
    scene_production = load_json(scene_production_path)
    scene_production_errors = validate_scene_production_data(
        scene_production,
        repo_root,
        str(plan.get("scene_slug")),
    )
    if scene_production_errors:
        raise PipelineError(
            "visual plan review requires exact audio-aligned scene production: "
            + " | ".join(scene_production_errors)
        )
    scene_production_binding = artifact_snapshot(
        scene_production_path,
        repo_root,
    )
    probes = parse_visual_plan_probe_evidence(args.probe or [], repo_root)
    draft = visual_plan_review_draft_data(
        plan,
        scene_plan_validation=validation,
        validation_binding=validation_binding,
        scene_production=scene_production,
        scene_production_binding=scene_production_binding,
        author_agent_id=author_agent_id,
        reviewer=str(args.reviewer),
        reviewer_model=str(args.reviewer_model),
        reasoning_effort=str(args.reasoning_effort),
        reviewer_agent_id=reviewer_agent_id,
        probe_evidence=probes,
    )
    write_json(Path(args.output), draft)
    print(
        json.dumps(
            {
                "visual_plan_review_draft": args.output,
                "scene_slug": draft.get("scene_slug"),
                "probe_count": len(probes),
            },
            ensure_ascii=False,
        )
    )
    return 0


