def design_readiness_inputs(args: argparse.Namespace) -> tuple[
    Path, dict[str, Any], dict[str, Any], dict[str, Any], dict[str, Any], str
]:
    repo_root = Path(args.repo_root).resolve()
    profile = load_json(resolve_stored_path(args.profile, repo_root))
    plan = load_json(resolve_stored_path(args.plan, repo_root))
    design_gate = load_json(resolve_stored_path(args.design_gate, repo_root))
    authoring_qc = load_json(resolve_stored_path(args.authoring_qc, repo_root))
    animatic = resolve_stored_path(args.animatic, repo_root)
    if not animatic.is_file():
        raise PipelineError("design readiness animatic does not exist")
    animatic_sha = artifact_snapshot(animatic, repo_root)["sha256"]
    return animatic, profile, plan, design_gate, authoring_qc, animatic_sha


