def animatic_repair_zero_progress_violations(
    *,
    output_root: Path,
    state_path: Path,
    receipt_path: Path,
    repo_root: Path,
) -> list[str]:
    """Return every non-control entry in an abandoned author's output root."""
    if output_root.is_symlink():
        return [relative_or_absolute(output_root, repo_root)]
    if not output_root.exists():
        return []
    if not output_root.is_dir():
        return [relative_or_absolute(output_root, repo_root)]
    exact_state = state_path.absolute()
    allowed_files = {
        exact_state,
        exact_state.with_name("._" + exact_state.name),
        (output_root / "rollout_totals_start.json").absolute(),
        receipt_path.absolute(),
    }
    violations: list[str] = []
    for candidate in output_root.rglob("*"):
        candidate_absolute = candidate.absolute()
        if candidate.is_symlink() or candidate.is_dir():
            violations.append(
                relative_or_absolute(candidate_absolute, repo_root)
            )
            continue
        if candidate_absolute in allowed_files and candidate.is_file():
            continue
        violations.append(
            relative_or_absolute(candidate_absolute, repo_root)
        )
    return sorted(set(violations))


